\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

\label{lemma-qf-and-qc-finite-fibre}
In diagram (\ref{equation-points-fibres}) the set (\ref{equation-fibre})
is finite if $f$ is of finite type and $f$ is quasi-finite at $x$.

\label{lemma-weird-sheaf}
There exists a sheaf of abelian groups $G$ on
$\Sch_\etale$ with the following properties
\begin{enumerate}
\item $G(\Spec(k)) = 0$ whenever $k$ is a field,
\item $G$ is limit preserving,
\item if $X \subset X'$ is a thickening, then $G(X) = G(X')$, and
\item $G$ is not zero.
\end{enumerate}

\label{lemma-finite-projective-modules-RS}
Example \ref{example-finite-projective-modules}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_V$ is a deformation category
for any finite dimensional vector space $V$ over $k$.

statement:
\begin{reference}
\cite[Proposition 3.7.1]{EGA1-second}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item For every field $K$ the induced map
$\Mor(\Spec(K), X) \to \Mor(\Spec(K), S)$
is injective.
\item The morphism $f$ is universally injective.
\item The morphism $f$ is radicial.
\item The diagonal morphism $\Delta_{X/S} : X \longrightarrow X \times_S X$
is surjective.
\end{enumerate}

statement_tex:
\label{lemma-universally-injective}
\begin{reference}
\cite[Proposition 3.7.1]{EGA1-second}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item For every field $K$ the induced map
$\Mor(\Spec(K), X) \to \Mor(\Spec(K), S)$
is injective.
\item The morphism $f$ is universally injective.
\item The morphism $f$ is radicial.
\item The diagonal morphism $\Delta_{X/S} : X \longrightarrow X \times_S X$
is surjective.
\end{enumerate}

\label{lemma-hierarchy}
A morphism $f : \mathcal{X} \to \mathcal{Y}$ of algebraic stacks is
\begin{enumerate}
\item a monomorphism if and only if $\Delta_{f, 1}$ is an isomorphism, and
\item representable by algebraic spaces if and only if $\Delta_{f, 1}$
is a monomorphism.
\end{enumerate}
Moreover, the second diagonal $\Delta_{f, 2}$ is always a monomorphism.

\label{lemma-deform-property}
Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (S \subset S')
}
$$
of thickenings. Assume $S \subset S'$ is a finite order thickening,
$X'$ flat over $S'$, $X = S \times_{S'} X'$, and
$Y = S \times_{S'} Y'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine}
\item
\label{item-finite-type}
$f$ is locally of finite type if and only if $f'$ is locally of finite type,
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite}
\item
\label{item-finite-presentation}
$f$ is locally of finite presentation if and only if $f'$ is locally of
finite presentation,
\item
\label{item-relative-dimension-d}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper}
\item $f$ is integral if and only if $f'$ is integral,
\label{item-integral}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite}
\item
\label{item-finite-locally-free}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-polarized-limits}
The stack in groupoids $\Polarizedstack$ is limit preserving
(Artin's Axioms, Definition \ref{artin-definition-limit-preserving}).

\label{lemma-non-descending-property-projective}
The properties
\begin{enumerate}
\item[] $\mathcal{P}(f) =$``$f$ is projective'', and
\item[] $\mathcal{P}(f) =$``$f$ is quasi-projective''
\end{enumerate}
are not Zariski local on the base. A fortiori, they are not fpqc local
on the base.

\label{lemma-counter-Grothendieck-existence}
Counter examples to algebraization of coherent sheaves.
\begin{enumerate}
\item Grothendieck's existence theorem as stated in
Cohomology of Schemes, Theorem \ref{coherent-theorem-grothendieck-existence}
is false if we drop the assumption that $X \to \Spec(A)$ is separated.
\item The stack of coherent sheaves $\Cohstack_{X/B}$
of Quot, Theorems \ref{quot-theorem-coherent-algebraic-general} and
\ref{quot-theorem-coherent-algebraic} is in general
not algebraic if we drop the assumption that $X \to S$ is separated
\item The functor $\Quotfunctor_{\mathcal{F}/X/B}$ of
Quot, Proposition \ref{quot-proposition-quot}
is not an algebraic space in general if we drop the assumption
that $X \to B$ is separated.
\end{enumerate}

