\label{lemma-complement-of-affine-does-not-contain-qc-dense-open}
Nonexistence quasi-compact opens of affines:
\begin{enumerate}
\item There exist an affine scheme $S$ and affine open $U \subset S$
such that there is no quasi-compact open $V \subset S$ with
$U \cap V = \emptyset$ and $U \cup V$ dense in $S$.
\item There exists an affine scheme $S$ and a closed point $s \in S$ such that
$S \setminus \{s\}$ does not contain a quasi-compact dense open.
\end{enumerate}

\label{lemma-pullback-meromorphic-sections-defined}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Pullbacks of meromorphic sections are defined
in each of the following cases
\begin{enumerate}
\item weakly associated points of $X$ are mapped
to points of codimension $0$ on $Y$,
\item $f$ is flat,
\item add more here as needed.
\end{enumerate}

\label{lemma-etale-nbhd-dominates-smooth}
\begin{slogan}
Smooth morphisms admit \'etale local sections.
\end{slogan}
\begin{reference}
See \cite[Corollaire 17.16.3 (ii)]{EGA4}.
\end{reference}
Let $f : X \to S$ be a smooth morphism of schemes.
Let $s \in S$ be a point in the image of $f$.
Then there exists an \'etale neighbourhood $(S', s') \to (S, s)$
and a $S$-morphism $S' \to X$.

\label{lemma-etale-not-dominated-zariski-finite-etale}
The \'etale cover $U \to X$ cannot be refined by any finite composition
of open immersions and finite \'etale morphisms.

