\label{lemma-composition-formally-smooth-etale-unramified}
Composition.
\begin{enumerate}
\item A composition of formally smooth transformations of functors is formally
smooth.
\item A composition of formally \'etale transformations of functors is formally
\'etale.
\item A composition of formally unramified transformations of functors is
formally unramified.
\end{enumerate}

\label{lemma-pullback-flat}
\begin{reference}
\cite[Expos\'e V, Corollary 1.7.1]{SGA4}
\end{reference}
Let
$(f, f^\sharp) :
(\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be a morphism of ringed topoi or ringed sites.
Then $f^*\mathcal{F}$ is a flat $\mathcal{O}_\mathcal{C}$-module
whenever $\mathcal{F}$ is a flat $\mathcal{O}_\mathcal{D}$-module.

\label{lemma-spaces-RS}
Example \ref{example-spaces}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any algebraic space $X$ over $k$.

\label{lemma-example-schematically-dense-missing-weakly-associated-point}
There exists a reduced scheme $X$ and a schematically dense open
$U \subset X$ such that some weakly associated point $x \in X$ is not in $U$.

\label{lemma-smooth-curves-h0}
There exist an open substack
$\Curvesstack^{smooth, h0} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{smooth}$,
\item $f_*\mathcal{O}_X = \mathcal{O}_S$, this holds after any base change,
and $f$ is smooth of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{smooth, h0}$,
\item $X$ is smooth, $\dim(X) = 1$, and $k = H^0(X, \mathcal{O}_X)$,
\item $X$ is smooth, $\dim(X) = 1$, and $X$ is geometrically connected,
\item $X$ is smooth, $\dim(X) = 1$, and $X$ is geometrically integral, and
\item $X_{\overline{k}}$ is a smooth curve.
\end{enumerate}
\end{enumerate}

